This Terraform configuration creates an encrypted AWS EFS file system with automatic backups enabled using the `aws_efs_backup_policy` resource. It also adds tags and lifecycle management for cost optimization.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the EFS file system will be created."
  type        = string
  default     = "us-east-1"
}

variable "efs_name" {
  description = "Name tag for the EFS file system."
  type        = string
  default     = "automatic-backup-efs"
}

resource "aws_efs_file_system" "this" {
  creation_token = var.efs_name
  encrypted      = true

  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }

  tags = {
    Name        = var.efs_name
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

resource "aws_efs_backup_policy" "this" {
  file_system_id = aws_efs_file_system.this.id

  backup_policy {
    status = "ENABLED"
  }
}

